{
  "decision-allocate-freight-overage-with-floor": "WITH ordered AS (SELECT shipment_id, capacity_used, ROW_NUMBER() OVER (ORDER BY capacity_used, shipment_id) - 1 AS fixed_count, SUM(capacity_used) OVER (ORDER BY capacity_used, shipment_id ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) AS remaining_capacity FROM shipments), pool AS (SELECT fixed_count, 100 - 20 * fixed_count AS cents, remaining_capacity FROM ordered WHERE (100 - 20 * fixed_count) * capacity_used >= 20 * remaining_capacity ORDER BY fixed_count LIMIT 1), shares AS (SELECT o.shipment_id, CASE WHEN o.fixed_count < p.fixed_count THEN 20 ELSE p.cents * o.capacity_used / p.remaining_capacity END AS base, CASE WHEN o.fixed_count < p.fixed_count THEN 0 ELSE (p.cents * o.capacity_used) % p.remaining_capacity END AS remainder FROM ordered AS o CROSS JOIN pool AS p), ranked AS (SELECT *, ROW_NUMBER() OVER (ORDER BY remainder DESC, shipment_id ASC) AS place, 100 - SUM(base) OVER () AS leftover FROM shares) SELECT shipment_id, base + CASE WHEN place <= leftover THEN 1 ELSE 0 END AS fee_cents FROM ranked ORDER BY shipment_id ASC",
  "decision-allocate-invoice-discount-before-page-subtotals": "WITH active AS (SELECT line_no, page_no, gross_cents, SUM(gross_cents) OVER () AS total_gross FROM charge_line WHERE void_flag = 0), shares AS (SELECT a.*, t.discount_cents, (t.discount_cents * a.gross_cents) / a.total_gross AS base, (t.discount_cents * a.gross_cents) % a.total_gross AS remainder FROM active AS a CROSS JOIN invoice_terms AS t), ranked AS (SELECT *, ROW_NUMBER() OVER (ORDER BY remainder DESC, line_no ASC) AS place, discount_cents - SUM(base) OVER () AS leftover FROM shares), allocated AS (SELECT page_no, gross_cents, base + CASE WHEN place <= leftover THEN 1 ELSE 0 END AS allocation FROM ranked) SELECT page_no, SUM(gross_cents) AS gross_cents, SUM(allocation) AS discount_cents, SUM(gross_cents) - SUM(allocation) AS net_cents FROM allocated GROUP BY page_no ORDER BY page_no ASC",
  "decision-allocate-kiln-shelf-space": "WITH lots AS (SELECT lot_id, COALESCE(lot_slots, piece_qty * slots_each) AS slots, mass_kg, priority_pts FROM waiting_lots), candidates AS (SELECT lot_id AS first_id, NULL AS second_id, slots, mass_kg, priority_pts FROM lots UNION ALL SELECT a.lot_id, b.lot_id, a.slots + b.slots, a.mass_kg + b.mass_kg, a.priority_pts + b.priority_pts FROM lots AS a JOIN lots AS b ON a.lot_id COLLATE BINARY < b.lot_id), best AS (SELECT first_id, second_id FROM candidates WHERE slots <= 10 AND mass_kg <= 12 ORDER BY priority_pts DESC, slots ASC, first_id COLLATE BINARY ASC, second_id COLLATE BINARY ASC LIMIT 1) SELECT lot_id FROM lots CROSS JOIN best WHERE lot_id IN (first_id, second_id) ORDER BY lot_id COLLATE BINARY ASC",
  "decision-allocate-printer-plates-to-chapter-pockets": "SELECT a.pocket_leaf AS first_leaf, b.pocket_leaf AS second_leaf, ABS(a.pocket_leaf - a.opener_leaf) + ABS(b.pocket_leaf - b.opener_leaf) AS drift_leaves, a.setup_min + b.setup_min AS total_min FROM pocket_offer AS a JOIN pocket_offer AS b ON a.pocket_leaf < b.pocket_leaf WHERE a.chapter_no = 1 AND b.chapter_no = 2 AND a.setup_min + b.setup_min <= 7 ORDER BY drift_leaves ASC, total_min ASC, first_leaf ASC, second_leaf ASC LIMIT 1"
}
